import{_ as d,o as a,c as s,ag as e}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"MovJSearch 关节寻位","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovJSearch.md","filePath":"3. 指令/1. 运动指令/MovJSearch.md","lastUpdated":1778862643000}'),r={name:"3. 指令/1. 运动指令/MovJSearch.md"};function i(o,t,n,h,l,c){return a(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="movjsearch-关节寻位" tabindex="-1">MovJSearch 关节寻位 <a class="header-anchor" href="#movjsearch-关节寻位" aria-label="Permalink to &quot;MovJSearch 关节寻位&quot;">​</a></h1><p>寻位指令（MovJSearch）是指在执行该关节运动指令的过程中，实时进行 <strong>IO 信号检测</strong>或<strong>轴力矩检测</strong>。一旦满足设定的触发条件，机器人将立即（或减速）停止当前运动，记录当前位置，并直接跳转执行后续指令。</p><p><strong>注意：该指令会打断路径的过渡效果。</strong></p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovJSearch(P, [V], [B], [C], [Tool], [Coord], [PayLoad], Type, Number, Value, [StopType], [StopDecScale], R, [SearchP], [Goto], [DO])</p><p>MovJSearch(目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], 搜索类型, 端口号, 触发值, [停止方式], [减速比例], 结果变量, [搜索点记录], [跳转行号], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>机器人计划运动到的终点。</td><td>必填</td></tr><tr><td>[V] / [B] / [C] / [Tool] / [Coord] / [PayLoad]</td><td>-</td><td>与 <code>MovJ</code> 指令定义一致（速度、过渡类型、过渡值、工具、坐标系、负载）。</td><td>过渡类型默认 FINE</td></tr><tr><td>Type</td><td>enum</td><td>检测类型：<br><code>DITrig</code>：物理数字输入口触发。<br><code>AITrig</code>：物理模拟量输入口触发。<br><code>SIMDITrig</code>：虚拟数字输入口触发。<br><code>SIMAITrig</code>：虚拟模拟量输入口触发。<br><code>TorqTrig</code>：力矩触发。</td><td>必填</td></tr><tr><td>Number</td><td>int</td><td>检测的编号。若为 <code>DITrig</code>，则为<strong>输入口号</strong>；若为 <code>TorqTrig</code>，则为<strong>轴编号</strong>。</td><td>必填</td></tr><tr><td>Value</td><td>real</td><td>检测的阈值。若为 <code>DITrig</code>，则为<strong>电平状态（0 或 1）</strong>；若为 <code>TorqTrig</code>，则为<strong>轴额定转矩的千分比</strong>。</td><td>必填</td></tr><tr><td>[StopType]</td><td>enum</td><td>停止类型：<br><code>HARDSTOP</code>：立即停止（默认值）。<br><code>SOFTSTOP</code>：减速停止。<br><code>DEFAULT</code>：缺省类型。</td><td>可选，默认 HARDSTOP</td></tr><tr><td>[StopDecScale]</td><td>real</td><td>仅在 <code>SOFTSTOP</code> 时有效，值越大减速越快。</td><td>可选</td></tr><tr><td>R</td><td>INT 变量</td><td>返回值：<br><code>0</code>：未触发条件，正常运动到终点结束。<br><code>1</code>：运动过程中满足条件触发。<br><code>2</code>：在运动起点处就已经满足条件。</td><td>必填</td></tr><tr><td>[SearchP]</td><td>APOS</td><td>返回满足触发条件那一时刻，机器人的真实坐标位置。</td><td>可选</td></tr><tr><td>[Goto]</td><td>label</td><td>若未触发信号（即 R=0），程序将跳转到指定的标签处执行。缺省则不跳转。</td><td>可选</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后可触发的额外 IO 操作。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：数字输入触发寻位</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJSearch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P2, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DITrig&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT0)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P3, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol><li>机器人以 50 速度向 P1 运动。</li><li>随后向 P2 运动，期间实时监控 <strong>16 号输入口</strong>。</li><li>如果 16 号口变为<strong>高电平 (1)</strong>：机器人立即停止向 P2 运动，将 <code>INT0</code> 设为 1，直接开始向 P3 运动。</li><li>如果运动到 P2 依然没有高电平：机器人到达 P2 后将 <code>INT0</code> 设为 0，继续向 P3 运动。</li></ol>`,15)])])}const g=d(r,[["render",i]]);export{k as __pageData,g as default};
